(function(root){
 'use strict';
 const steps=[{label:'Face',slots:['head','eyes','nose','mouth']},{label:'Hair',slots:['hair','facialHair','headwear']},{label:'Details',slots:['scars','eyewear','faceCovering','augmentation']},{label:'Clothing',slots:['clothing','neckwear']},{label:'Review',slots:[]}];
 const colors={head:['skin'],eyes:['iris'],hair:['hair','hairAccent'],clothing:['clothing'],facialHair:['facialHair'],headwear:['headwear'],neckwear:['neckwear']};
 function mount(container,system,initial,{onChange=()=>{},allowedOptions={}}={}){
  const numeric=root.Portraits,clone=v=>JSON.parse(JSON.stringify(v));let value=system.normalize(initial),step=0,history=[];const initialValue=system.defaultAppearance();
  const options=slot=>system.choices(slot).filter(o=>!Object.hasOwn(allowedOptions,slot)||allowedOptions[slot].includes(o.id));
  function constrain(){for(const slot of Object.keys(value.parts)){const choices=options(slot);if(!choices.length)throw Error('No allowed '+slot+' choices.');if(!choices.some(o=>o.id===value.parts[slot]))value.parts[slot]=choices[0].id;}}
  constrain();
  function change(action){history.push(clone(value));if(history.length>30)history.shift();action();constrain();draw();onChange(clone(value));}
  function button(text,action){const b=document.createElement('button');b.type='button';b.textContent=text;b.onclick=action;return b;}
  function colorField(parent,key){if(!Object.hasOwn(value.colors,key))return;const label=document.createElement('label');label.className='portrait-color';label.textContent=system.pack.colors[key].label;const input=document.createElement('input');input.type='color';input.value=numeric.hex(value.colors[key]);input.setAttribute('aria-label',system.pack.colors[key].label+' color');input.onchange=()=>change(()=>value.colors[key]=numeric.rgb(input.value));label.append(input);parent.append(label);}
  function draw(){container.replaceChildren();container.classList.add('portrait-wizard');const tabs=document.createElement('div');tabs.className='wizard-tabs';tabs.setAttribute('role','tablist');tabs.setAttribute('aria-label','Portrait creation steps');container.append(tabs);
   steps.forEach((s,i)=>{const b=button(s.label,()=>{step=i;draw();});b.setAttribute('role','tab');b.setAttribute('aria-selected',String(i===step));b.id='portrait-step-'+i;b.setAttribute('aria-controls','portrait-step-panel');tabs.append(b);});
   const panel=document.createElement('section');panel.id='portrait-step-panel';panel.setAttribute('role','tabpanel');panel.setAttribute('aria-labelledby','portrait-step-'+step);panel.className='wizard-panel';container.append(panel);
   for(const slot of steps[step].slots){if(!system.pack.slots[slot])continue;const card=document.createElement('div');card.className='wizard-part';const label=document.createElement('label');label.textContent=system.pack.slots[slot].label;const select=document.createElement('select');select.setAttribute('aria-label',system.pack.slots[slot].label);for(const choice of options(slot)){const option=document.createElement('option');option.value=String(choice.id);option.textContent=choice.label;select.append(option);}select.value=String(value.parts[slot]);select.onchange=()=>change(()=>value.parts[slot]=Number(select.value));label.append(select);card.append(label);const selected=options(slot).find(o=>o.id===value.parts[slot]);if(selected?.hasAsset)for(const key of colors[slot]||[])colorField(card,key);panel.append(card);}
   if(step===2&&steps[2].slots.some(slot=>options(slot).find(o=>o.id===value.parts[slot])?.hasAsset)){const shared=document.createElement('div');shared.className='wizard-part';const note=document.createElement('p');note.textContent='Shared accessory colour';shared.append(note);colorField(shared,'accessory');panel.append(shared);}
   if(step===4){const summary=document.createElement('p');summary.textContent='Your portrait is ready. Review the picture, then save or export below.';panel.append(summary);const list=document.createElement('ul');for(const [slot,id] of Object.entries(value.parts)){const item=document.createElement('li');item.textContent=system.pack.slots[slot].label+': '+system.choices(slot).find(o=>o.id===id).label;list.append(item);}panel.append(list);}
   const actions=document.createElement('div');actions.className='wizard-actions';const undo=button('Undo',()=>{if(history.length){value=history.pop();draw();onChange(clone(value));}});undo.disabled=!history.length;actions.append(undo);
   if(step<4){actions.append(button('Reset this tab',()=>change(()=>{for(const slot of steps[step].slots){if(!system.pack.slots[slot])continue;value.parts[slot]=initialValue.parts[slot];for(const key of colors[slot]||[])value.colors[key]=initialValue.colors[key];}if(step===2)value.colors.accessory=initialValue.colors.accessory;})));actions.append(button('Randomize this tab',()=>change(()=>{for(const slot of steps[step].slots){if(!system.pack.slots[slot])continue;const choices=options(slot);value.parts[slot]=choices[Math.floor(Math.random()*choices.length)].id;}})));}
   container.append(actions);const navigation=document.createElement('div');navigation.className='wizard-navigation';const back=button('Back',()=>{step--;draw();});back.disabled=step===0;const next=button('Next',()=>{step++;draw();});next.disabled=step===steps.length-1;navigation.append(back,next);container.append(navigation);
  }
  draw();return {getAppearance:()=>clone(value),setAppearance:code=>{value=system.normalize(code);constrain();draw();onChange(clone(value));},destroy:()=>container.replaceChildren()};
 }
 root.PortraitWizard={mount};
})(globalThis);
